CREATE TABLE IF NOT EXISTS `categories` (`id` TEXT NOT NULL, `name` TEXT NOT NULL COLLATE NOCASE, `sortOrder` INTEGER NOT NULL, `isActive` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, `groupId` TEXT NOT NULL DEFAULT 'home', `homeAtRoot` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`));
CREATE UNIQUE INDEX IF NOT EXISTS `index_categories_groupId_name` ON `categories` (`groupId`, `name`);
CREATE TABLE IF NOT EXISTS `category_groups` (`id` TEXT NOT NULL, `name` TEXT NOT NULL COLLATE NOCASE, `sortOrder` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE UNIQUE INDEX IF NOT EXISTS `index_category_groups_name` ON `category_groups` (`name`);
CREATE TABLE IF NOT EXISTS `capture_tasks` (`id` TEXT NOT NULL, `tempPath` TEXT NOT NULL, `categoryId` TEXT NOT NULL, `categoryName` TEXT NOT NULL, `rootTreeUri` TEXT NOT NULL, `mediaKind` TEXT NOT NULL, `stage` TEXT NOT NULL, `targetUri` TEXT, `error` TEXT, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, `groupId` TEXT NOT NULL DEFAULT 'home', `groupName` TEXT DEFAULT NULL, `photoDateStampText` TEXT DEFAULT NULL, `sourcePath` TEXT DEFAULT NULL, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_capture_tasks_stage` ON `capture_tasks` (`stage`);
CREATE INDEX IF NOT EXISTS `index_capture_tasks_createdAt` ON `capture_tasks` (`createdAt`);
CREATE TABLE IF NOT EXISTS `document_drafts` (`id` TEXT NOT NULL, `sourcePath` TEXT NOT NULL, `categoryId` TEXT NOT NULL, `categoryName` TEXT NOT NULL, `rootTreeUri` TEXT NOT NULL, `quadValue` TEXT NOT NULL, `effectValue` TEXT NOT NULL, `quarterTurns` INTEGER NOT NULL, `stage` TEXT NOT NULL, `editingSlot` INTEGER, `replacementPath` TEXT, `createdAt` INTEGER NOT NULL, `groupId` TEXT NOT NULL DEFAULT 'home', `groupName` TEXT DEFAULT NULL, `processingVersion` INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(`id`));
CREATE UNIQUE INDEX IF NOT EXISTS `index_document_drafts_editingSlot` ON `document_drafts` (`editingSlot`);
CREATE TABLE IF NOT EXISTS `directory_operations` (`id` TEXT NOT NULL, `kind` TEXT NOT NULL, `categoryId` TEXT, `sourceGroupId` TEXT NOT NULL, `targetGroupId` TEXT NOT NULL, `rootTreeUri` TEXT NOT NULL, `sourceGroupName` TEXT, `targetGroupName` TEXT, `sourceName` TEXT NOT NULL, `targetName` TEXT NOT NULL, `stateJson` TEXT NOT NULL, `stage` TEXT NOT NULL, `error` TEXT, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, `slot` INTEGER, `targetBeforeCategoryId` TEXT DEFAULT NULL, PRIMARY KEY(`id`));
CREATE UNIQUE INDEX IF NOT EXISTS `index_directory_operations_slot` ON `directory_operations` (`slot`);
